CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('customer','seller','rider','admin')),status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sellers(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id) ON DELETE CASCADE,store_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS riders(id BIGSERIAL PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS customer_private_details(user_id BIGINT PRIMARY KEY REFERENCES users(id),phone TEXT,home_address TEXT);
CREATE TABLE IF NOT EXISTS hubs(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,city TEXT DEFAULT 'Karachi',is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS lockers(id BIGSERIAL PRIMARY KEY,hub_id BIGINT REFERENCES hubs(id),locker_code TEXT,compartment_size TEXT,status TEXT DEFAULT 'available',UNIQUE(hub_id,locker_code));
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,seller_id BIGINT REFERENCES sellers(id),name TEXT NOT NULL,description TEXT DEFAULT '',price_pkr INTEGER NOT NULL,stock_qty INTEGER DEFAULT 0,parcel_size TEXT DEFAULT 'Small',image_file TEXT DEFAULT 'shirt.svg',is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders(id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES users(id),preferred_hub_id BIGINT REFERENCES hubs(id),alternative_hub_id BIGINT REFERENCES hubs(id),allow_alternative BOOLEAN DEFAULT FALSE,total_pkr INTEGER DEFAULT 0,status TEXT DEFAULT 'placed',payment_status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),product_id BIGINT REFERENCES products(id),seller_id BIGINT REFERENCES sellers(id),quantity INTEGER,unit_price_pkr INTEGER);
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),amount_pkr INTEGER,status TEXT,provider_reference TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS deliveries(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),rider_id BIGINT REFERENCES riders(id),status TEXT DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS qr_tokens(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),token TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,expired_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS qr_scan_logs(id BIGSERIAL PRIMARY KEY,qr_token_id BIGINT REFERENCES qr_tokens(id),result TEXT,scanned_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS returns(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),customer_id BIGINT REFERENCES users(id),reason TEXT,status TEXT DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),message TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,sender_id BIGINT REFERENCES users(id),receiver_id BIGINT REFERENCES users(id),message TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS complaints(id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES users(id),order_id BIGINT REFERENCES orders(id),message TEXT,status TEXT DEFAULT 'open');
CREATE TABLE IF NOT EXISTS order_status_history(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),status TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT REFERENCES users(id),action TEXT,details JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO hubs(name,city) SELECT v,'Karachi' FROM (VALUES('DHA Hub'),('Clifton Hub'),('Saddar Hub'),('Gulshan-e-Iqbal Hub'),('PECHS Hub')) x(v) WHERE NOT EXISTS(SELECT 1 FROM hubs h WHERE h.name=x.v);
INSERT INTO lockers(hub_id,locker_code,compartment_size) SELECT h.id,v.c,v.s FROM hubs h CROSS JOIN (VALUES('S01','S'),('S02','S'),('S03','S'),('S04','S'),('M01','M'),('M02','M'),('M03','M'),('L01','L')) v(c,s) WHERE NOT EXISTS(SELECT 1 FROM lockers l WHERE l.hub_id=h.id AND l.locker_code=v.c);
